import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.BW2T23B9.js";const p=JSON.parse('{"title":"配置 AI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai-configuration.md","filePath":"guide/ai-configuration.md","lastUpdated":null}'),i={name:"guide/ai-configuration.md"};function l(o,t,h,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="配置-ai" tabindex="-1">配置 AI <a class="header-anchor" href="#配置-ai" aria-label="Permalink to &quot;配置 AI&quot;">​</a></h1><p>AI 不是核心学习流程的前置条件。未配置模型时，课程、复习、错题和本地课程检索继续可用。</p><h2 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td>Provider preset</td><td>服务商预设或 custom</td></tr><tr><td>Base URL</td><td>API 根地址</td></tr><tr><td>API key</td><td>服务凭据</td></tr><tr><td>Chat model</td><td>流式对话与解释模型</td></tr><tr><td>JSON model</td><td>结构化生成模型</td></tr><tr><td>Strict schema mode</td><td>对 JSON schema 的要求与回退策略</td></tr></tbody></table><p>预设包括 DeepSeek、OpenAI、Moonshot、Ollama 和 Custom。具体模型名由用户配置，文档不假设远端默认值长期有效。</p><h2 id="配置顺序" tabindex="-1">配置顺序 <a class="header-anchor" href="#配置顺序" aria-label="Permalink to &quot;配置顺序&quot;">​</a></h2><ol><li>打开设置中的 AI Tools。</li><li>选择 provider preset。</li><li>输入 base URL 与 API key；本地 Ollama 可按本地服务配置处理。</li><li>分别选择 Chat model 与 JSON model。</li><li>执行连接测试。</li><li>检查延迟和错误信息。</li><li>保存后从 AI Hub 发起最小文本请求。</li></ol><h2 id="连接测试" tabindex="-1">连接测试 <a class="header-anchor" href="#连接测试" aria-label="Permalink to &quot;连接测试&quot;">​</a></h2><p>连接测试只证明当前 endpoint、凭据和最小请求可达，不证明所有结构化生成功能都受支持。JSON schema 不受支持时，引擎可按配置回退到 JSON object；结果仍需本地解析和校验。</p><h2 id="密钥存储" tabindex="-1">密钥存储 <a class="header-anchor" href="#密钥存储" aria-label="Permalink to &quot;密钥存储&quot;">​</a></h2><p>原生平台使用可用的安全存储实现。Web 或缺少安全存储插件的平台仅在会话内持有凭据，并在界面中显示限制。</p><p>密钥不得进入：</p><ul><li>普通日志。</li><li>Prompt 缓存键。</li><li>脱敏报告。</li><li>课程 JSON。</li><li>文档或截图。</li></ul><h2 id="超时、重试与取消" tabindex="-1">超时、重试与取消 <a class="header-anchor" href="#超时、重试与取消" aria-label="Permalink to &quot;超时、重试与取消&quot;">​</a></h2><p>请求包含功能名、Prompt 版本、输出上限、超时、幂等键和取消令牌。安全重试最多执行受控次数。取消是协作式操作：客户端停止接收和处理结果，不保证远端立即停止计费。</p><h2 id="预算" tabindex="-1">预算 <a class="header-anchor" href="#预算" aria-label="Permalink to &quot;预算&quot;">​</a></h2><p>AI 预算由统一管理器判断，可配置每日软限制与硬限制。软限制用于提示，硬限制阻止新请求。Token 和成本显示是本地估算时，应明确不等于服务商账单。</p><h2 id="故障判定" tabindex="-1">故障判定 <a class="header-anchor" href="#故障判定" aria-label="Permalink to &quot;故障判定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误</th><th>处理</th></tr></thead><tbody><tr><td>401 / 403</td><td>检查 key、权限和 base URL</td></tr><tr><td>模型不存在</td><td>检查模型名与 endpoint</td></tr><tr><td>schema 不支持</td><td>允许受控回退或更换 JSON model</td></tr><tr><td>超时</td><td>降低输入规模、检查网络或本地服务</td></tr><tr><td>输出不可解析</td><td>保留原始错误状态，不直接写入课程</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/ai">AI 伴学</a></li><li><a href="/docs/guide/ai-workflows">AI 工作流</a></li><li><a href="/docs/guide/data-and-privacy">本地数据与隐私</a></li></ul>',21)])])}const m=a(i,[["render",l]]);export{p as __pageData,m as default};
